package service

import (
	"fmt"
	"sync"
)

// User represents a user in the system
type User struct {
	ID    string `json:"id"`
	Name  string `json:"name"`
	Email string `json:"email"`
}

// UserService handles user-related business logic
type UserService struct {
	users  map[string]User
	mutex  sync.RWMutex
	nextID int
}

// NewUserService creates and returns a new UserService
func NewUserService() *UserService {
	return &UserService{
		users:  make(map[string]User),
		nextID: 1,
	}
}

// GetAllUsers returns all users
func (s *UserService) GetAllUsers() []User {
	s.mutex.RLock()
	defer s.mutex.RUnlock()
	var list []User
	for _, u := range s.users {
		list = append(list, u)
	}
	return list
}

// CreateUser creates a new user and returns it
func (s *UserService) CreateUser(u User) User {
	s.mutex.Lock()
	defer s.mutex.Unlock()
	u.ID = fmt.Sprintf("%d", s.nextID)
	s.nextID++
	s.users[u.ID] = u
	return u
}

// GetUserByID returns a user by ID
func (s *UserService) GetUserByID(id string) (User, bool) {
	s.mutex.RLock()
	defer s.mutex.RUnlock()
	u, ok := s.users[id]
	return u, ok
}

package api

import (
	"encoding/json"
	"net/http"
	"strings"

	"rep-1/internal/service" // Assuming module name is rep-1
)

// UserHandler handles HTTP requests for users
type UserHandler struct {
	Service *service.UserService
}

// NewUserHandler creates and returns a new UserHandler
func NewUserHandler(s *service.UserService) *UserHandler {
	return &UserHandler{Service: s}
}

// HandleUsers manages requests to /users
func (h *UserHandler) HandleUsers(w http.ResponseWriter, r *http.Request) {
	switch r.Method {
	case http.MethodGet:
		users := h.Service.GetAllUsers()
		json.NewEncoder(w).Encode(users)

	case http.MethodPost:
		var u service.User
		if err := json.NewDecoder(r.Body).Decode(&u); err != nil {
			http.Error(w, err.Error(), http.StatusBadRequest)
			return
		}
		createdUser := h.Service.CreateUser(u)
		w.WriteHeader(http.StatusCreated)
		json.NewEncoder(w).Encode(createdUser)

	default:
		http.Error(w, "Method not allowed", http.StatusMethodNotAllowed)
	}
}

// HandleUserByID manages requests to /users/{id}
func (h *UserHandler) HandleUserByID(w http.ResponseWriter, r *http.Request) {
	id := strings.TrimPrefix(r.URL.Path, "/users/")
	if id == "" {
		http.NotFound(w, r)
		return
	}

	switch r.Method {
	case http.MethodGet:
		u, ok := h.Service.GetUserByID(id)
		if !ok {
			http.NotFound(w, r)
			return
		}
		json.NewEncoder(w).Encode(u)
	default:
		http.Error(w, "Method not allowed", http.StatusMethodNotAllowed)
	}
}

package main

import (
	"log"
	"net/http"

	"experiment/internal/api"
	"experiment/internal/service"
)

func main() {
	userService := service.NewUserService()
	userHandler := api.NewUserHandler(userService)

	http.HandleFunc("/users", userHandler.HandleUsers)
	http.HandleFunc("/users/", userHandler.HandleUserByID)

	log.Println("Server starting on :8080...")
	if err := http.ListenAndServe(":8080", nil); err != nil {
		log.Fatal(err)
	}
}

package service

import (
	"reflect"
	"testing"
)

func TestNewUserService(t *testing.T) {
	s := NewUserService()
	if s == nil {
		t.Errorf("NewUserService() returned nil")
	}
	if len(s.users) != 0 {
		t.Errorf("NewUserService() users map is not empty, got %d", len(s.users))
	}
	if s.nextID != 1 {
		t.Errorf("NewUserService() nextID is not 1, got %d", s.nextID)
	}
}

func TestUserService_CreateUser(t *testing.T) {
	s := NewUserService()
	user := User{Name: "Test User", Email: "test@example.com"}
	createdUser := s.CreateUser(user)

	if createdUser.ID != "1" {
		t.Errorf("CreateUser() ID not as expected, got %s", createdUser.ID)
	}
	if createdUser.Name != user.Name || createdUser.Email != user.Email {
		t.Errorf("CreateUser() user data mismatch, got %+v", createdUser)
	}
	if len(s.users) != 1 {
		t.Errorf("CreateUser() users map size not 1, got %d", len(s.users))
	}
	if s.users["1"].Name != user.Name {
		t.Errorf("CreateUser() user not found in map or data mismatch")
	}

	user2 := User{Name: "Another User", Email: "another@example.com"}
	createdUser2 := s.CreateUser(user2)
	if createdUser2.ID != "2" {
		t.Errorf("CreateUser() second user ID not as expected, got %s", createdUser2.ID)
	}
}

func TestUserService_GetAllUsers(t *testing.T) {
	s := NewUserService()
	user1 := User{Name: "User One", Email: "one@example.com"}
	user2 := User{Name: "User Two", Email: "two@example.com"}
	s.CreateUser(user1)
	s.CreateUser(user2)

	allUsers := s.GetAllUsers()
	if len(allUsers) != 2 {
		t.Errorf("GetAllUsers() returned %d users, expected 2", len(allUsers))
	}

	// Check if users are present (order might vary due to map iteration)
	foundUser1 := false
	foundUser2 := false
	for _, u := range allUsers {
		if u.Name == user1.Name && u.Email == user1.Email {
			foundUser1 = true
		}
		if u.Name == user2.Name && u.Email == user2.Email {
			foundUser2 = true
		}
	}
	if !foundUser1 || !foundUser2 {
		t.Errorf("GetAllUsers() did not return all created users")
	}
}

func TestUserService_GetUserByID(t *testing.T) {
	s := NewUserService()
	user := User{Name: "Find Me", Email: "findme@example.com"}
	createdUser := s.CreateUser(user)

	foundUser, ok := s.GetUserByID(createdUser.ID)
	if !ok {
		t.Errorf("GetUserByID() failed to find user with ID %s", createdUser.ID)
	}
	if !reflect.DeepEqual(foundUser, createdUser) {
		t.Errorf("GetUserByID() returned wrong user. Got %+v, Expected %+v", foundUser, createdUser)
	}

	_, ok = s.GetUserByID("nonexistent")
	if ok {
		t.Errorf("GetUserByID() found a nonexistent user")
	}
}

package api

import (
	"bytes"
	"encoding/json"
	"net/http"
	"net/http/httptest"
	"strings"
	"testing"

	"experiment/internal/service"
)

func TestUserHandler_HandleUsers_GET(t *testing.T) {
	userService := service.NewUserService()
	handler := NewUserHandler(userService)

	// Add some initial users
	userService.CreateUser(service.User{Name: "Alice", Email: "alice@example.com"})
	userService.CreateUser(service.User{Name: "Bob", Email: "bob@example.com"})

	req, err := http.NewRequest("GET", "/users", nil)
	if err != nil {
		t.Fatal(err)
	}

	rr := httptest.NewRecorder()
	handler.HandleUsers(rr, req)

	if status := rr.Code; status != http.StatusOK {
		t.Errorf("handler returned wrong status code: got %v want %v",
			status, http.StatusOK)
	}

	var users []service.User
	if err := json.NewDecoder(rr.Body).Decode(&users); err != nil {
		t.Fatalf("could not decode response: %v", err)
	}

	if len(users) != 2 {
		t.Errorf("expected 2 users, got %d", len(users))
	}
	// Further checks for user data can be added
}

func TestUserHandler_HandleUsers_POST(t *testing.T) {
	userService := service.NewUserService()
	handler := NewUserHandler(userService)

	userJSON := `{"Name": "Charlie", "Email": "charlie@example.com"}`
	req, err := http.NewRequest("POST", "/users", strings.NewReader(userJSON))
	if err != nil {
		t.Fatal(err)
	}
	req.Header.Set("Content-Type", "application/json")

	rr := httptest.NewRecorder()
	handler.HandleUsers(rr, req)

	if status := rr.Code; status != http.StatusCreated {
		t.Errorf("handler returned wrong status code: got %v want %v",
			status, http.StatusCreated)
	}

	var createdUser service.User
	if err := json.NewDecoder(rr.Body).Decode(&createdUser); err != nil {
		t.Fatalf("could not decode response: %v", err)
	}

	if createdUser.ID == "" {
		t.Errorf("expected user ID to be set, got empty")
	}
	if createdUser.Name != "Charlie" || createdUser.Email != "charlie@example.com" {
		t.Errorf("created user data mismatch: got %+v", createdUser)
	}

	// Verify it's in the service
	_, ok := userService.GetUserByID(createdUser.ID)
	if !ok {
		t.Errorf("user not found in service after creation")
	}
}

func TestUserHandler_HandleUserByID_GET(t *testing.T) {
	userService := service.NewUserService()
	handler := NewUserHandler(userService)

	user := userService.CreateUser(service.User{Name: "David", Email: "david@example.com"})

	req, err := http.NewRequest("GET", "/users/"+user.ID, nil)
	if err != nil {
		t.Fatal(err)
	}

	rr := httptest.NewRecorder()
	handler.HandleUserByID(rr, req)

	if status := rr.Code; status != http.StatusOK {
		t.Errorf("handler returned wrong status code: got %v want %v",
			status, http.StatusOK)
	}

	var foundUser service.User
	if err := json.NewDecoder(rr.Body).Decode(&foundUser); err != nil {
		t.Fatalf("could not decode response: %v", err)
	}

	if foundUser.ID != user.ID || foundUser.Name != user.Name {
		t.Errorf("found user data mismatch: got %+v, expected %+v", foundUser, user)
	}
}

func TestUserHandler_HandleUserByID_GET_NotFound(t *testing.T) {
	userService := service.NewUserService()
	handler := NewUserHandler(userService)

	req, err := http.NewRequest("GET", "/users/999", nil)
	if err != nil {
		t.Fatal(err)
	}

	rr := httptest.NewRecorder()
	handler.HandleUserByID(rr, req)

	if status := rr.Code; status != http.StatusNotFound {
		t.Errorf("handler returned wrong status code for not found: got %v want %v",
			status, http.StatusNotFound)
	}
}

func TestUserHandler_HandleUsers_MethodNotAllowed(t *testing.T) {
	userService := service.NewUserService()
	handler := NewUserHandler(userService)

	req, err := http.NewRequest("PUT", "/users", nil)
	if err != nil {
		t.Fatal(err)
	}

	rr := httptest.NewRecorder()
	handler.HandleUsers(rr, req)

	if status := rr.Code; status != http.StatusMethodNotAllowed {
		t.Errorf("handler returned wrong status code for method not allowed: got %v want %v",
			status, http.StatusMethodNotAllowed)
	}
}

func TestUserHandler_HandleUserByID_MethodNotAllowed(t *testing.T) {
	userService := service.NewUserService()
	handler := NewUserHandler(userService)

	req, err := http.NewRequest("POST", "/users/1", nil) // POST to /users/id is not allowed
	if err != nil {
		t.Fatal(err)
	}

	rr := httptest.NewRecorder()
	handler.HandleUserByID(rr, req)

	if status := rr.Code; status != http.StatusMethodNotAllowed {
		t.Errorf("handler returned wrong status code for method not allowed: got %v want %v",
			status, http.StatusMethodNotAllowed)
	}
}
